<?= view('layout/header', ['title' => $item ? 'Edit product' : 'Add product']) ?><h1><?= $item ? 'Edit product' : 'Add product' ?></h1><div class="panel"><form method="post" enctype="multipart/form-data" action="<?= $item ? site_url('products/' . $item['id']) : site_url('products') ?>"><?= csrf_field() ?><label for="name">Product name</label><input id="name" name="name" required maxlength="100" value="<?= esc(old('name', $item['name'] ?? ''), 'attr') ?>"><label for="price">Price (₱)</label><input id="price" name="price" type="number" min="0.01" max="99999999.99" step="0.01" required value="<?= esc(old('price', $item['price'] ?? ''), 'attr') ?>"><label for="stock">Stock quantity</label><input id="stock" name="stock_quantity" type="number" min="0" max="2147483647" step="1" required value="<?= esc(old('stock_quantity', $item['stock_quantity'] ?? '0'), 'attr') ?>"><label for="image">Product image (JPG, PNG, WebP; max 2 MB)</label><input id="image" name="image" type="file" accept="image/jpeg,image/png,image/webp"><?php if ($item && $url = \App\Libraries\ImageUpload::url($item['image'], 'products')): ?><p>Current image: <img class="thumb" src="<?= esc($url, 'attr') ?>" alt="Current product image"></p><?php endif ?><p><button>Save product</button> <a href="<?= site_url('products') ?>">Cancel</a></p></form></div><?= view('layout/footer') ?>
